// Local disposable fixture generated by phase4_http.py. Requires Playwright + Chromium.
const {chromium}=require('playwright');const fs=require('fs');const path=require('path');
(async()=>{
 const fixture=JSON.parse(fs.readFileSync(process.env.TEST_FIXTURE||'runtime/phase4-fixture.json','utf8'));let checks=0;const ok=(x,label)=>{if(!x)throw Error(label);checks++;console.log('PASS '+label);};
 const browser=await chromium.launch({executablePath:process.env.TEST_BROWSER,headless:true,args:['--no-sandbox']});
 const context=await browser.newContext();await context.addCookies([{name:'PHPSESSID',value:fixture.session,domain:'127.0.0.1',path:'/'}]);const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const base='http://127.0.0.1:8088/';const url=tab=>base+`doctor-panel.php?doctor=${fixture.doctor}&clinic=${fixture.clinic}&tab=${tab}`;
 for(const [width,height,label] of [[1440,1000,'desktop'],[820,1180,'tablet'],[390,844,'mobile']]){
  await page.setViewportSize({width,height});
  for(const tab of ['dashboard','profile','clinics','services','schedule','calendar','bookings','history','staff','notifications','events']){
   await page.goto(url(tab));await page.evaluate(()=>document.fonts.ready);
   ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),`${label} ${tab} no horizontal page overflow`);
   ok(!(await page.locator('body').innerText()).match(/Fatal error|Warning:|در پردازش درخواست خطایی رخ داد/),`${label} ${tab} renders without PHP errors`);
   if(tab==='dashboard')await page.screenshot({path:`runtime/doctor-${label}.png`,fullPage:true});
  }
  for(const view of ['week','month']){
   await page.goto(url('calendar')+`&view=${view}&date=${encodeURIComponent(fixture.date)}`);ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),`${label} ${view} calendar constrained`);
  }
  await page.goto(base+`doctor.php?id=${fixture.doctor}&clinic=${fixture.clinic}&date=${encodeURIComponent(fixture.date)}`);await page.evaluate(()=>document.fonts.ready);ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),`${label} public profile responsive`);await page.screenshot({path:`runtime/public-${label}.png`,fullPage:true});
 }
 await page.goto(url('profile'));await page.locator('[name=professional_title]').fill('متخصص قلب و عروق');await page.locator('[name=education]').fill('دانش‌آموخته دانشگاه علوم پزشکی');await page.locator('[name=bio]').fill('ارائه خدمات ویزیت و مشاوره در مطب، با هماهنگی قبلی.');await page.locator('[name=experience_years]').fill('12');await page.getByRole('button',{name:'ذخیره پروفایل',exact:true}).click();ok((await page.locator('[role=status]').textContent()).includes('ذخیره'),'profile form submits successfully');
 await page.locator('input[type=file]').setInputFiles({name:'unsafe.php',mimeType:'image/jpeg',buffer:Buffer.from('<?php echo "unsafe";')});await page.getByRole('button',{name:'بارگذاری تصویر'}).click();ok((await page.locator('[role=alert]').innerText()).includes('فرمت یا ابعاد تصویر مجاز نیست'),'disguised PHP upload rejected');
 const image=process.env.TEST_IMAGE||'runtime/test-photo.png';await page.locator('input[type=file]').setInputFiles(image);await page.getByRole('button',{name:'بارگذاری تصویر'}).click();ok((await page.locator('[role=status]').textContent()).includes('تصویر ذخیره شد'),'real multipart image upload succeeds');
 const response=await context.request.get(base+`photo.php?id=${fixture.doctor}`);ok(response.status()===200&&response.headers()['content-type']==='image/jpeg','photo endpoint returns reencoded JPEG');const bytes=await response.body();ok(bytes[0]===255&&bytes[1]===216,'uploaded PNG converted to JPEG');
 await page.goto(url('clinics'));await page.locator('details').first().locator('summary').click();const select=page.locator('details').first().locator('select[name=province_id]');const value=await select.inputValue();ok(await page.locator('details').first().locator('select[name=city_id] option:checked').getAttribute('data-province')===value,'dependent province/city selection retains matching city');
 await page.goto(url('calendar')+`&view=month&date=${encodeURIComponent(fixture.date)}`);await page.locator('.calendar-day').first().click();ok(page.url().includes('view=day'),'monthly day opens real daily calendar');
 ok(errors.length===0,'no client JavaScript exceptions');console.log('SUCCESS '+checks+' browser checks');await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
